  const paths = new Set<string>();
  for (const line of readFileSync(path, "utf8").split(/\r?\n/).filter(Boolean)) {
    const value = JSON.parse(line) as unknown;
    if (!Array.isArray(value) || value.some((entry) => typeof entry !== "string")) {
